PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS "User" ("id" TEXT PRIMARY KEY NOT NULL,"displayName" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS "SpotifyConnection" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL UNIQUE,"accessTokenEncrypted" TEXT NOT NULL,"refreshTokenEncrypted" TEXT NOT NULL,"expiresAt" DATETIME NOT NULL,"scope" TEXT NOT NULL,"spotifyUserId" TEXT,"lastSyncedAt" DATETIME,"invalidatedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "SpotifyArtist" ("id" TEXT PRIMARY KEY NOT NULL,"spotifyId" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"spotifyUrl" TEXT NOT NULL,"imageUrl" TEXT,"genresJson" TEXT NOT NULL DEFAULT '[]',"metadataJson" TEXT NOT NULL DEFAULT '{}',"syncedAt" DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS "SpotifyTopArtistPeriod" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"artistId" TEXT NOT NULL,"period" TEXT NOT NULL,"rank" INTEGER NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"syncedAt" DATETIME NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("artistId") REFERENCES "SpotifyArtist"("id") ON DELETE CASCADE,UNIQUE("userId","artistId","period"));
CREATE INDEX IF NOT EXISTS "SpotifyTopArtistPeriod_userId_period_idx" ON "SpotifyTopArtistPeriod"("userId","period");
CREATE TABLE IF NOT EXISTS "ArtistPreference" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"spotifyId" TEXT,"spotifyUrl" TEXT,"imageUrl" TEXT,"weight" TEXT NOT NULL DEFAULT 'INTERESTING',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,UNIQUE("userId","normalizedName"));
CREATE TABLE IF NOT EXISTS "GenrePreference" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,UNIQUE("userId","normalizedName"));
CREATE TABLE IF NOT EXISTS "ExcludedArtist" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,UNIQUE("userId","normalizedName"));
CREATE TABLE IF NOT EXISTS "ExcludedGenre" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,UNIQUE("userId","normalizedName"));
CREATE TABLE IF NOT EXISTS "Venue" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL UNIQUE,"aliasesJson" TEXT NOT NULL DEFAULT '[]',"city" TEXT NOT NULL DEFAULT 'Amsterdam',"address" TEXT,"latitude" REAL,"longitude" REAL,"providerIdsJson" TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS "Event" ("id" TEXT PRIMARY KEY NOT NULL,"canonicalKey" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"normalizedTitle" TEXT NOT NULL,"type" TEXT NOT NULL DEFAULT 'UNKNOWN',"startAt" DATETIME NOT NULL,"endAt" DATETIME,"timeZone" TEXT NOT NULL DEFAULT 'Europe/Amsterdam',"localDate" TEXT NOT NULL,"city" TEXT NOT NULL,"latitude" REAL,"longitude" REAL,"genresJson" TEXT NOT NULL DEFAULT '[]',"classificationsJson" TEXT NOT NULL DEFAULT '[]',"ticketStatus" TEXT NOT NULL DEFAULT 'NOT_CHECKED',"rawTicketStatus" TEXT,"officialUrl" TEXT NOT NULL,"imageUrl" TEXT,"lastCheckedAt" DATETIME NOT NULL,"lastSyncedAt" DATETIME NOT NULL,"venueId" TEXT,FOREIGN KEY("venueId") REFERENCES "Venue"("id"));
CREATE INDEX IF NOT EXISTS "Event_startAt_idx" ON "Event"("startAt");
CREATE TABLE IF NOT EXISTS "EventArtist" ("id" TEXT PRIMARY KEY NOT NULL,"eventId" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"externalId" TEXT,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE,UNIQUE("eventId","normalizedName"));
CREATE TABLE IF NOT EXISTS "EventSource" ("id" TEXT PRIMARY KEY NOT NULL,"eventId" TEXT NOT NULL,"provider" TEXT NOT NULL,"externalId" TEXT NOT NULL,"url" TEXT NOT NULL,"rawStatus" TEXT,"lastSeenAt" DATETIME NOT NULL,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE,UNIQUE("provider","externalId"));
CREATE TABLE IF NOT EXISTS "SavedEvent" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE,UNIQUE("userId","eventId"));
CREATE TABLE IF NOT EXISTS "DismissedEvent" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE,UNIQUE("userId","eventId"));
CREATE TABLE IF NOT EXISTS "EventImpression" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"firstShownAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastShownAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"count" INTEGER NOT NULL DEFAULT 1,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE,UNIQUE("userId","eventId"));
CREATE TABLE IF NOT EXISTS "NotificationSettings" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL UNIQUE,"enabled" BOOLEAN NOT NULL DEFAULT false,"minimumScore" INTEGER NOT NULL DEFAULT 70,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "NotificationLog" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"provider" TEXT NOT NULL,"sentAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE,UNIQUE("userId","eventId","provider"));
CREATE TABLE IF NOT EXISTS "SyncRun" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL,"kind" TEXT NOT NULL,"provider" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'RUNNING',"startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" DATETIME,"found" INTEGER NOT NULL DEFAULT 0,"added" INTEGER NOT NULL DEFAULT 0,"updated" INTEGER NOT NULL DEFAULT 0,"skipped" INTEGER NOT NULL DEFAULT 0,"failed" INTEGER NOT NULL DEFAULT 0,"errorMessage" TEXT,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "SyncRun_userId_kind_startedAt_idx" ON "SyncRun"("userId","kind","startedAt");
